static void Timer2_Callback(void) {
    //timerTickCount++;
    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
      /* Call tick handler */
    	xPortSysTickHandler();
    }
}

static void TIMER16_Callback(void) {
    ulHighFrequencyTimerTicks++;

}

void timer_init(void)
{
	uint32_t t2clk = STM32F0Timer_GetTimerClockHz(TIMER2);
	if (!STM32F0Timer_ConfigurePeriodUs(TIMER2, t2clk, 1000U)) {
	        while (1);
	    }
	STM32F0Timer_SetUpdateCallback(TIMER2, Timer2_Callback);
	STM32F0Timer_EnableUpdateInterrupt(TIMER2, true);
	STM32F0Timer_Start(TIMER2);

    //---- This timer is for debugging of FreeRTOS for Task States ------//
    ConfigureTimerForRunTimeStats();
}

void led_gpio_init(void) {
    GPIO_InitTypeDef GPIO_InitStruct = {0};

    /* Enable GPIOC clock for LED on PC8 */
    GPIO_EnableClock(GPIOC);

    /* Configure PC8 as output */
    GPIO_InitStruct.Pin = GPIO_PIN_8;
    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT;
    GPIO_InitStruct.Ot = GPIO_OTYPE_PP;
    GPIO_InitStruct.Speed = GPIO_SPEED_LOW;
    GPIO_InitStruct.Pull = GPIO_PULL_NO;
    GPIO_Init(GPIOC, &GPIO_InitStruct);

    /* Configure PC8 as output */
    GPIO_InitStruct.Pin = GPIO_PIN_9;
    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT;
    GPIO_InitStruct.Ot = GPIO_OTYPE_PP;
    GPIO_InitStruct.Speed = GPIO_SPEED_LOW;
    GPIO_InitStruct.Pull = GPIO_PULL_NO;
    GPIO_Init(GPIOC, &GPIO_InitStruct);
}

void SystemClock_Config_48MHz(void) {
    RCC_Config config = {
        .system_clock_source = CLOCK_SOURCE_PLL,
        .target_frequency = SYSTEM_CLOCK_48MHZ,
        .hse_enabled = true,
        .pll_enabled = true,
        .pll_source = PLL_SOURCE_HSE,
        .pll_multiplier = 6,  // HSE 8MHz * 6 = 48MHz
        .ahb_prescaler = AHB_PRESCALER_1,
        .apb_prescaler = APB_PRESCALER_1,
        .hsi48_enabled = false,
        .css_enabled = true
    };

    RCC_Init(&config);

    if(FLASH_ConfigureForFrequency(48000000) != FLASH_STATUS_OK)
    {
    	while(1);
    }
}

