#define MAX_IDLE_COUNT 614491u
void tmr1secCallBack(TimerHandle_t xTimer)
{
	if(xTimer == tmr_1sec)
	{
		if(IdleCounter < MAX_IDLE_COUNT)
		{
			CPU_Usage = 100 - ((IdleCounter * 100) / MAX_IDLE_COUNT);
		}
		IdleCounter = 0;
	}
}

int main(void)
{
	SystemClock_Config_48MHz();
	led_gpio_init();

    timer_init();
    STM32F0Timer_Stop(TIMER2);

    xTaskCreate(
        LedTask,
        "LED",
        128,
        NULL,
        tskIDLE_PRIORITY + 2,
        &ledTaskHandle
    );


    xTaskCreate(
    	Monitoring_Task,
        "Monitor_Task",
        128,
        NULL,
        tskIDLE_PRIORITY + 2,
        &monitoringTaskHandle
    );

    UART_App_Init();

    tmr_1sec = xTimerCreate("1Sec_Timer",
    						pdMS_TO_TICKS(1000),
							pdTRUE,
							NULL,
							tmr1secCallBack);

    xTimerStart(tmr_1sec, 0);
    STM32F0Timer_Start(TIMER2);

    vTaskStartScheduler();

    /* Main loop - toggle LED */
    while (1) {
    		//GPIO_TogglePin(GPIOC, GPIO_PIN_8);
            Delay_ms(pdMS_TO_TICKS(100));
    }
}


static inline char* TaskStateDecode(uint8_t state)
{
	if(state==0)
		return "eRunning";
	else if(state==1)
		return "eReady";
	else if(state==2)
		return "eBlocked";
	else if(state==3)
		return "eSuspended";
	else if(state==4)
		return "eDeleted";
	else if(state==5)
		return "eInvalid";
	else
		return "undefined";
}

